use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserPersonalApiKeyKeyHashAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserPersonalApiKeyKeyHashAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getKeyHash returns null on a freshly created holder.
     */
    public function testKeyHashNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyKeyHashAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isKeyHashAssigned());
        $this->assertNull($holder->getKeyHash());
    }
}
class ImplWithUserPersonalApiKeyKeyHashAttributeHolderUnitTest
